CREATE TABLE STUDENT(STU_NO NUMBER(8) PRIMARY KEY,STU_NAME VARCHAR2(20),STU_DEPT VARCHAR2(20),STU_GRADE NUMBER,STU_CLASS VARCHAR2(1),STU_GENDER VARCHAR2(1),STU_HEIGHT NUMBER,STU_WEIGHT NUMBER);
CREATE TABLE SUBJECT(SUB_NO NUMBER(3) PRIMARY KEY,SUB_NAME VARCHAR2(20),SUB_PROF VARCHAR2(20),SUB_GRADE NUMBER,SUB_DEPT VARCHAR2(20));
CREATE TABLE ENROL(SUB_NO NUMBER REFERENCES SUBJECT(SUB_NO),STU_NO NUMBER REFERENCES STUDENT(STU_NO),ENR_GRADE NUMBER,PRIMARY KEY(SUB_NO,STU_NO));
